export const config = {
  matcher: ["/ch/:path*", "/en/:path*"],
};

function pass() {
  return new Response(null, {
    headers: {
      "x-middleware-next": "1",
      "x-page-map": "on",
    },
  });
}

function routeKey(url) {
  const pairs = [...url.searchParams.entries()].sort((a, b) => {
    if (a[0] !== b[0]) return a[0] < b[0] ? -1 : 1;
    if (a[1] !== b[1]) return a[1] < b[1] ? -1 : 1;
    return 0;
  });
  return url.pathname + "?" + pairs.map(([key, value]) => key + "=" + value).join("&");
}

export default function middleware(request) {
  const url = new URL(request.url);
  if (!url.search) return pass();
  const file = pages[routeKey(url)];
  if (!file) return pass();
  return new Response(null, {
    headers: { "x-middleware-rewrite": file },
  });
}
